+    fn fiat_hash_from_env() -> Option<Shake256> {
+        let ops_len = std::env::var("POINT_ADD_HASH_OPS_LEN")
+            .ok()
+            .and_then(|s| s.parse::<u64>().ok())?;
+        let mut hasher = Shake256::default();
+        hasher.update(b"quantum_ecc-fiat-shamir-v2");
+        hasher.update(&ops_len.to_le_bytes());
+        Some(hasher)
+    }
+    pub(crate) fn update_fiat_hash_op(hasher: &mut Shake256, op: &Op) {
+        hasher.update(&[op.kind as u8]);
+        hasher.update(&op.q_control2.0.to_le_bytes());
+        hasher.update(&op.q_control1.0.to_le_bytes());
+        hasher.update(&op.q_target.0.to_le_bytes());
+        hasher.update(&op.c_target.0.to_le_bytes());
+        hasher.update(&op.c_condition.0.to_le_bytes());
+        hasher.update(&op.r_target.0.to_le_bytes());
+    }
+    pub(crate) fn clone_fiat_hash(&self) -> Option<Shake256> {
+        self.fiat_hash.clone()
+    }
+    fn push_op(&mut self, op: Op) {
+        self.counted_ops += 1;
+        self.counted_kind_ops[op.kind as usize] += 1;
+        self.counted_phase_kind_ops[op.kind as usize] += 1;
+        if let Some(hasher) = &mut self.fiat_hash {
+            Self::update_fiat_hash_op(hasher, &op);
+        }
+        if !self.count_only {
+            self.ops.push(op);
+        }

+pub fn build() -> Vec<Op> {
+    if std::env::var("POINT_ADD_DIALOG_ROUTE").ok().as_deref() != Some("1") {
+        return trailmix_port::build_builder().ops;
+    }

+    // FOLD diff INTO pa:
+    //   pa := (pos_a + 1 + lo_a) - (pos_b + 1 + lo_b)
+    //       = pos_a - pos_b + lo_a - lo_b.
+    // The two constants commute across the subtract, so use one constant add
+    // instead of two.
+    {
+        let par: Vec<&QReg> = pa.iter().collect();
+        let pbr: Vec<&QReg> = pb.iter().collect();
+        sub_refs(circ, &par, &pbr); // pa -= pos_b
+    }
+    add_pa(circ, &pa, lo_a as i64 - lo_b as i64); // pa = bitlen(a) - bitlen(b) = diff
+
+    body(circ, &pa); // USE pa (= diff)
+
+    {
+        let par: Vec<&QReg> = pa.iter().collect();
+        let pbr: Vec<&QReg> = pb.iter().collect();
+        add_refs(circ, &par, &pbr); // pa += pos_b
+    }
+    add_pa(circ, &pa, lo_b as i64 - lo_a as i64); // pa = pos_a
+
+    // un-deposit (self-inverse clean=false calls, reverse order).
+    bit_length_lean_middle(circ, &bw, &pb, |_| false); // pb -> nb
+    xor_const(circ, &pb, nb); // pb -> 0
+    bit_length_lean_middle(circ, &aw, &pa, |_| false); // pa -> na
+    xor_const(circ, &pa, na); // pa -> 0

+    search_tail_nonce(&circ.b, tail_q0, tail_q1);
+
+    if let Some(nonce) = std::env::var("TRAILMIX_TAIL_NONCE")
+        .ok()
+        .and_then(|s| s.parse::<u64>().ok())
+    {
+        circ.set_section("trailmix_tail_nonce");
+        for i in 0..TRAILMIX_TAIL_NONCE_BITS {
+            let q = if (nonce >> i) & 1 == 1 {
+                &out[1]
+            } else {
+                &out[0]
+            };
+            circ.x(q);
+            circ.x(q);
+        }
+    }
